-- Audit rows FIRST, so old_value and the new version are read pre-update. Only
-- rows whose path SET genuinely differs produce history -- the comparison sorts
-- and joins the JSON elements rather than comparing the raw strings, so a
-- difference in separator style alone ('a","b' vs 'a", "b') does NOT count as a
-- change and does not bump version. This is what makes the file idempotent and
-- safe to run alongside PR #905's migration in either order.
INSERT INTO requirement_change
  (requirement_id, version, field, old_value, new_value,
   change_type, change_summary, changed_by, changed_at)
SELECT r.id, r.version + 1, 'impl_paths', r.impl_paths, t.impl_paths,
       'modified', 'merged PR(s) changed', 'github-actions[bot]', '2026-07-30T00:00:00Z'
FROM requirement r
JOIN impl_path_target t ON t.requirement_id = r.id
WHERE (SELECT group_concat(value, char(10))
       FROM (SELECT value FROM json_each(r.impl_paths) ORDER BY value))
   IS NOT
      (SELECT group_concat(value, char(10))
       FROM (SELECT value FROM json_each(t.impl_paths) ORDER BY value));

UPDATE requirement
SET impl_paths = (SELECT t.impl_paths FROM impl_path_target t
                  WHERE t.requirement_id = requirement.id),
    version    = version + 1,
    updated_at = '2026-07-30T00:00:00Z',
    updated_by = 'github-actions[bot]'
WHERE id IN (SELECT requirement_id FROM impl_path_target)
  AND (SELECT group_concat(value, char(10))
       FROM (SELECT value FROM json_each(requirement.impl_paths) ORDER BY value))
   IS NOT
      (SELECT group_concat(value, char(10))
       FROM (SELECT value FROM json_each(
               (SELECT t.impl_paths FROM impl_path_target t
                WHERE t.requirement_id = requirement.id)) ORDER BY value));

DROP TABLE impl_path_target;

COMMIT;
